{
  "translations": [
    {
      "source_qa_id": "medical_discoveries__chemical_or_structural_class__012__target__target_class_2__en__core",
      "language": "zh",
      "question": "青霉素中与β-内酰胺核心稠合的是什么环？",
      "expected_answer": "噻唑烷环",
      "answer_aliases": [
        "噻唑环"
      ],
      "translation_note": "fused to is translated as 稠合 (chemical term for fused rings)"
    },
    {
      "source_qa_id": "medical_discoveries__chemical_or_structural_class__012__target__target_class_2__en__surface_001",
      "language": "zh",
      "question": "哪种特定的环结构连接在青霉素的β-内酰胺核心上？",
      "expected_answer": "噻唑烷环",
      "answer_aliases": [
        "噻唑环"
      ],
      "translation_note": "attached to is translated as 连接在"
    },
    {
      "source_qa_id": "medical_discoveries__chemical_or_structural_class__012__target__target_class_2__en__surface_002",
      "language": "zh",
      "question": "青霉素的特征是β-内酰胺核心与哪种类型的环稠合？",
      "expected_answer": "噻唑烷环",
      "answer_aliases": [
        "噻唑环"
      ],
      "translation_note": "features is translated as 特征是"
    },
    {
      "source_qa_id": "medical_discoveries__chemical_or_structural_class__012__target__target_class_2__en__surface_003",
      "language": "zh",
      "question": "在结构上，什么环与β-内酰胺核心结合形成了青霉素？",
      "expected_answer": "噻唑烷环",
      "answer_aliases": [
        "噻唑环"
      ],
      "translation_note": "structurally is translated as 在结构上"
    },
    {
      "source_qa_id": "medical_discoveries__chemical_or_structural_class__012__neighbor__neighbor_class_3__en__core",
      "language": "zh",
      "question": "由A链和B链组成的人胰岛素蛋白属于什么结构类别？",
      "expected_answer": "异二聚体",
      "answer_aliases": [
        "胰岛素"
      ],
      "translation_note": "structural class is translated as 结构类别"
    },
    {
      "source_qa_id": "medical_discoveries__chemical_or_structural_class__012__neighbor__neighbor_class_3__en__surface_001",
      "language": "zh",
      "question": "就其蛋白质结构而言，既然人胰岛素具有A链和B链，它被认为是什么？",
      "expected_answer": "异二聚体",
      "answer_aliases": [
        "胰岛素"
      ],
      "translation_note": "in terms of its protein structure is translated as 就其蛋白质结构而言"
    },
    {
      "source_qa_id": "medical_discoveries__chemical_or_structural_class__012__neighbor__neighbor_class_3__en__surface_002",
      "language": "zh",
      "question": "人胰岛素蛋白由A链和B链组成，它属于什么类型的分子？",
      "expected_answer": "异二聚体",
      "answer_aliases": [
        "胰岛素"
      ],
      "translation_note": "what type of molecule is translated as 属于什么类型的分子"
    },
    {
      "source_qa_id": "medical_discoveries__chemical_or_structural_class__012__neighbor__neighbor_class_3__en__surface_003",
      "language": "zh",
      "question": "用什么术语来描述人胰岛素的双链结构？",
      "expected_answer": "异二聚体",
      "answer_aliases": [
        "胰岛素"
      ],
      "translation_note": "what term describes is translated as 用什么术语来描述"
    }
  ]
